import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { PageHeader, StickyScrollWithFilters } from 'components';
import { TableDataType } from 'components/Table/types';
import {
  StickyNavigationTopOffsetProvider,
  useCurrentPage,
  usePageFilterApplied,
} from 'hooks';
import { KPIS_TITLE_MAP } from 'shared/constants';
import { StyledGridContainer, StyledHomeContainer } from 'shared/Styles';

import {
  PERFORMANCE_TOOL_MAX_VISIBLE_FILTERS,
  PERFORMANCE_TOOL_NAVIGATION_TEST_ID,
  PERFORMANCE_TOOL_PAGE_NAME,
  SOURCE_STATUS_VISIBLE_FILTER_FIELDS,
} from '../../constants';
import { kpiDrillDownTableMock_sourcestatus } from '../Kpis/MarketShareOfficial/__mocks__/Table';
import { RefreshStatus } from './components/RefreshStatus/RefreshStatus';
import { getPerformanceToolBreadcrumbHref } from './utils';

export const SourceStatus = () => {
  const { currentPage } = useCurrentPage();
  const { formatMessage } = useIntl();

  const { applied } = usePageFilterApplied(currentPage);
  const kpiMapped = KPIS_TITLE_MAP[applied.kpis as keyof typeof KPIS_TITLE_MAP];
  const pageTitle = useMemo(
    () =>
      formatMessage(
        {
          id: 'ValueCreation.PerformanceTool.sourceStatus.title',
        },
        {
          kpi: kpiMapped,
        },
      ),
    [kpiMapped, formatMessage],
  );

  const marketShareVersion = localStorage.getItem('market-share-version');

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: PERFORMANCE_TOOL_PAGE_NAME,
          visibleFields: SOURCE_STATUS_VISIBLE_FILTER_FIELDS,
          maxVisibleFilters: PERFORMANCE_TOOL_MAX_VISIBLE_FILTERS,
        }}
        breadcrumbs={{
          pageList: [
            { href: '/value-creation', pageName: 'Value Creation' },
            {
              href: getPerformanceToolBreadcrumbHref(
                applied.kpis as string,
                marketShareVersion,
              ),
              pageName: 'Performance Tool',
            },
            {
              href: `/value-creation/performance-tool/${applied.kpis}/source-status`,
              pageName: `${kpiMapped} Source Status`,
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
        dataTestId={PERFORMANCE_TOOL_NAVIGATION_TEST_ID}
      />

      <StickyNavigationTopOffsetProvider
        navigationTestId={PERFORMANCE_TOOL_NAVIGATION_TEST_ID}
      >
        <StyledGridContainer $isResponsivePage>
          <StyledHomeContainer>
            <PageHeader
              title={pageTitle}

              loading={!applied.kpis}
            />
          </StyledHomeContainer>
          <RefreshStatus
            data={kpiDrillDownTableMock_sourcestatus as TableDataType}
          />
        </StyledGridContainer>
      </StickyNavigationTopOffsetProvider>
    </>
  );
};
